  "inlineSchema": "// Prisma Schema for Dynamic Landing Page, Seller Dashboard, and System Admin API\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\nmodel User {\n  id           String   @id @default(uuid())\n  name         String\n  email        String   @unique\n  phone        String\n  passwordHash String\n  role         String   @default(\"SUPER_SELLER\") // SYSTEM_USER, SUPER_SELLER, SELLER_ADMIN\n  status       String   @default(\"PENDING_APPROVAL\") // PENDING_APPROVAL, APPROVED, REJECTED, ACTIVE, SUSPENDED\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  shops                Shop[]\n  applications         SuperSellerApplication[] @relation(\"ApplicantUser\")\n  reviewedApplications SuperSellerApplication[] @relation(\"ReviewerUser\")\n  repairJobsAssigned   RepairJob[]              @relation(\"AssignedUser\")\n  repairUpdates        RepairUpdate[]\n}\n\nmodel SuperSellerApplication {\n  id                     String    @id @default(uuid())\n  userId                 String\n  user                   User      @relation(\"ApplicantUser\", fields: [userId], references: [id], onDelete: Cascade)\n  shopName               String\n  shopType               String\n  phone                  String\n  address                String\n  businessDocUrl         String?\n  status                 String    @default(\"PENDING\") // PENDING, APPROVED, REJECTED\n  reviewedBySystemUserId String?\n  reviewedByUser         User?     @relation(\"ReviewerUser\", fields: [reviewedBySystemUserId], references: [id])\n  reviewedAt             DateTime?\n  rejectionReason        String?\n  createdAt              DateTime  @default(now())\n  updatedAt              DateTime  @updatedAt\n\n  @@index([status])\n}\n\nmodel Shop {\n  id             String   @id @default(uuid())\n  ownerUserId    String\n  ownerUser      User     @relation(fields: [ownerUserId], references: [id], onDelete: Cascade)\n  name           String\n  type           String\n  description    String?\n  phone          String\n  whatsappNumber String\n  address        String\n  latitude       Float\n  longitude      Float\n  isActive       Boolean  @default(false)\n  isVerified     Boolean  @default(false)\n  openingHours   String?\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  products         Product[]\n  offers           Offer[]\n  enquiries        WhatsAppEnquiry[]\n  visitorAnalytics VisitorAnalytics[]\n  repairCustomers  RepairCustomer[]\n  repairJobs       RepairJob[]\n\n  @@index([isActive, isVerified, latitude, longitude])\n}\n\nmodel Category {\n  id        String    @id @default(uuid())\n  name      String\n  slug      String    @unique\n  type      String    @default(\"accessory\") // e.g. \"accessory\", \"repair\"\n  isActive  Boolean   @default(true)\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n  products  Product[]\n}\n\nmodel Product {\n  id                  String   @id @default(uuid())\n  shopId              String\n  shop                Shop     @relation(fields: [shopId], references: [id], onDelete: Cascade)\n  categoryId          String\n  category            Category @relation(fields: [categoryId], references: [id])\n  name                String\n  brand               String?\n  sku                 String?\n  pricePaise          Int\n  compareAtPricePaise Int?\n  stock               Int      @default(0)\n  status              String   @default(\"ACTIVE\")\n  description         String?\n  createdAt           DateTime @default(now())\n  updatedAt           DateTime @updatedAt\n\n  images    ProductImage[]\n  enquiries WhatsAppEnquiry[]\n\n  @@index([shopId, status])\n}\n\nmodel ProductImage {\n  id        String   @id @default(uuid())\n  productId String\n  product   Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n  url       String\n  altText   String?\n  position  Int      @default(0)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel Offer {\n  id            String    @id @default(uuid())\n  shopId        String\n  shop          Shop      @relation(fields: [shopId], references: [id], onDelete: Cascade)\n  title         String\n  discountType  String    @default(\"PERCENTAGE\") // PERCENTAGE or FIXED\n  discountValue Int\n  startsAt      DateTime?\n  endsAt        DateTime?\n  status        String    @default(\"ACTIVE\")\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n}\n\nmodel WhatsAppEnquiry {\n  id            String   @id @default(uuid())\n  shopId        String\n  shop          Shop     @relation(fields: [shopId], references: [id], onDelete: Cascade)\n  productId     String?\n  product       Product? @relation(fields: [productId], references: [id])\n  customerName  String\n  customerPhone String\n  message       String\n  whatsappUrl   String\n  ipAddress     String?\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  @@index([shopId, createdAt])\n}\n\nmodel VisitorAnalytics {\n  id         String   @id @default(uuid())\n  visitorId  String\n  ipHash     String\n  userAgent  String?\n  pageUrl    String\n  actionType String // PAGE_VIEW, NEARBY_SEARCH, WHATSAPP_ENQUIRY_CLICK\n  shopId     String?\n  shop       Shop?    @relation(fields: [shopId], references: [id], onDelete: SetNull)\n  timestamp  DateTime @default(now())\n\n  @@index([timestamp, actionType])\n}\n\nmodel RepairCustomer {\n  id        String      @id @default(uuid())\n  shopId    String\n  shop      Shop        @relation(fields: [shopId], references: [id], onDelete: Cascade)\n  name      String\n  phone     String\n  email     String?\n  createdAt DateTime    @default(now())\n  updatedAt DateTime    @updatedAt\n  jobs      RepairJob[]\n}\n\nmodel RepairJob {\n  id                 String          @id @default(uuid())\n  shopId             String\n  shop               Shop            @relation(fields: [shopId], references: [id], onDelete: Cascade)\n  customerName       String\n  customerPhone      String\n  repairCustomerId   String?\n  repairCustomer     RepairCustomer? @relation(fields: [repairCustomerId], references: [id])\n  deviceId           String\n  problemDescription String\n  status             String          @default(\"SUBMITTED\") // SUBMITTED, UNDER_REVIEW, QUOTED, APPROVED, IN_PROGRESS, READY, COMPLETED, CANCELLED, NOT_REPAIRABLE\n  estimatedCostPaise Int?\n  isSellable         Boolean         @default(false)\n  assignedToUserId   String?\n  assignedToUser     User?           @relation(\"AssignedUser\", fields: [assignedToUserId], references: [id])\n  createdAt          DateTime        @default(now())\n  updatedAt          DateTime        @updatedAt\n\n  updates RepairUpdate[]\n\n  @@index([shopId, status, createdAt])\n}\n\nmodel RepairUpdate {\n  id                 String    @id @default(uuid())\n  repairJobId        String\n  repairJob          RepairJob @relation(fields: [repairJobId], references: [id], onDelete: Cascade)\n  authorUserId       String\n  authorUser         User      @relation(fields: [authorUserId], references: [id])\n  status             String\n  note               String\n  estimatedCostPaise Int?\n  createdAt          DateTime  @default(now())\n  updatedAt          DateTime  @updatedAt\n}\n\nmodel LandingPageSection {\n  id          String   @id @default(uuid())\n  key         String   @unique\n  title       String\n  subtitle    String?\n  body        String?\n  imageUrl    String?\n  ctaLabel    String?\n  ctaUrl      String?\n  isPublished Boolean  @default(true)\n  sortOrder   Int      @default(0)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n}\n",
